 'view_definition',pg_get_viewdef('public.card_public'::regclass,true)=' SELECT card_code,
    business_name,
    review_url
   FROM card;',
 'no_unreviewed_triggers',NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal),
 'relation_owners',NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','v','S') AND pg_get_userbyid(c.relowner)<>'postgres')
) AS strict_preflight;
